{
  "name": "CLUB 61",
  "description": "A feature-rich gaming platform clone featuring WinGo, Aviator, Mines, and Wallet management with real-time simulation.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React, { useState, useEffect } from 'react';
import { View } from '../types';
import { Flame, Tv, Volume2, Share2, Crown } from 'lucide-react';
import { transactions, subscribeToBalance } from '../services/mockFirebase';

interface HomeProps {
  setView: (view: View) => void;
}

const Home: React.FC<HomeProps> = ({ setView }) => {
  const [tickerItems, setTickerItems] = useState<string[]>([]);

  const generateFakeWinner = () => {
      const id = Math.floor(10000 + Math.random() * 90000);
      const suffix = Math.floor(10 + Math.random() * 90);
      const amount = (Math.random() * 5000 + 100).toFixed(2);
      const games = ['WinGo', 'Aviator', 'Mines', 'Lucky Wheel', 'Dog Road'];
      const game = games[Math.floor(Math.random() * games.length)];
      return `Member ID: ${id}***${suffix} Won ₹${amount} in ${game}!`;
  };

  useEffect(() => {
      const initialItems = Array(5).fill(null).map(generateFakeWinner);
      setTickerItems(initialItems);

      const unsub = subscribeToBalance(() => {
           const recentWithdrawal = transactions.find(t => t.type === 'WITHDRAW' && t.status === 'PROCESSING');
           if (recentWithdrawal) {
               const realMsg = `Member ID: YOU Won ₹${recentWithdrawal.amount} Withdrawal!`;
               setTickerItems(prev => [realMsg, ...prev].slice(0, 20));
           }
      });

      const interval = setInterval(() => {
          setTickerItems(prev => {
              const newItem = generateFakeWinner();
              const newArray = [newItem, ...prev];
              if (newArray.length > 20) newArray.pop();
              return newArray;
          });
      }, 3000);

      return () => {
          clearInterval(interval);
          unsub();
      }
  }, []);

  const handleShare = async () => {
      const shareData = {
          title: 'CLUB 61',
          text: 'Join the elite CLUB 61 and win big! Play WinGo, Aviator and more.',
          url: window.location.href
      };

      if (navigator.share) {
          try {
              await navigator.share(shareData);
          } catch (err) {
              console.log('Error sharing:', err);
          }
      } else {
          navigator.clipboard.writeText(window.location.href);
          alert('Club Invite link copied!');
      }
  };

  const GameCard = ({ title, desc, color, onClick, icon }: any) => (
    <div onClick={onClick} className={`bg-[#1e293b] rounded-2xl overflow-hidden cursor-pointer group hover:ring-2 hover:ring-yellow-500 transition-all border border-slate-700/50 shadow-lg`}>
        <div className={`h-28 bg-${color}-900/50 relative flex items-center justify-center overflow-hidden`}>
           <div className="text-5xl transform group-hover:scale-110 transition-transform duration-300 drop-shadow-2xl">{icon}</div>
        </div>
        <div className="p-3">
            <h4 className="font-bold text-white text-sm">{title}</h4>
            <p className="text-[10px] text-slate-400 uppercase tracking-tighter font-medium">{desc}</p>
        </div>
    </div>
  );

  return (
    <div className="pb-24 font-sans animate-in fade-in duration-500">
      <div className="bg-gradient-to-b from-[#1a1c2e] to-[#0a0f1d] pb-6 rounded-b-[2.5rem] shadow-2xl relative">
        <div className="p-4 flex justify-between items-center">
            <div className="flex items-center gap-2">
                <Crown size={24} className="text-yellow-500 fill-yellow-500" />
                <h1 className="text-2xl font-black italic tracking-tighter text-white gold-text">CLUB 61</h1>
            </div>
            <div className="flex gap-2">
                <button onClick={handleShare} className="bg-yellow-500/10 p-2 rounded-full text-yellow-500 border border-yellow-500/20 hover:bg-yellow-500/20 transition-colors">
                    <Share2 size={18} />
                </button>
                <div className="bg-slate-800/50 p-2 rounded-full text-slate-300 border border-slate-700 hover:bg-slate-700 transition-colors">
                    <Tv size={18} />
                </div>
            </div>
        </div>

        <div className="mx-4 mt-2 h-44 bg-gradient-to-br from-[#1e293b] to-[#0a0f1d] rounded-[1.5rem] flex items-center justify-center shadow-xl relative overflow-hidden group border border-yellow-500/20">
            <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1541339907198-e08756ebafe3?auto=format&fit=crop&q=80&w=800')] bg-cover bg-center opacity-30 group-hover:scale-105 transition-transform duration-1000"></div>
            <div className="relative z-10 text-center px-4">
                <h2 className="text-4xl font-black text-white drop-shadow-2xl italic tracking-tighter gold-text">ELITE REWARDS</h2>
                <p className="text-xs font-bold text-yellow-100 mt-2 bg-black/40 backdrop-blur-sm px-4 py-1.5 rounded-full border border-yellow-500/20 uppercase tracking-widest">Join the Club Experience</p>
            </div>
        </div>

        <div className="mx-4 mt-4 bg-[#111827] rounded-full py-2.5 px-5 flex items-center gap-3 overflow-hidden border border-slate-800 shadow-inner h-11">
            <Volume2 size={16} className="text-yellow-500 shrink-0 animate-pulse" />
            <div className="flex-1 h-full relative overflow-hidden">
                 <div className="flex flex-col gap-3 animate-[slideUp_15s_linear_infinite]">
                     {tickerItems.map((item, i) => (
                         <div key={i} className="text-xs text-slate-300 whitespace-nowrap font-bold tracking-tight">
                             {item}
                         </div>
                     ))}
                 </div>
            </div>
        </div>
      </div>

      <div className="flex overflow-x-auto gap-3 p-4 no-scrollbar">
        {['Popular', 'Lottery', 'Casino', 'Slots', 'Sports'].map((cat, i) => (
            <button key={cat} className={`flex-shrink-0 px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${i === 0 ? 'bg-yellow-600 text-black shadow-lg shadow-yellow-500/20' : 'bg-[#1e293b] text-slate-400 border border-slate-700/50'}`}>
                {cat}
            </button>
        ))}
      </div>

      <div className="px-4 pb-4">
        <h3 className="flex items-center gap-2 text-white font-black text-sm mb-4 uppercase tracking-widest">
            <Flame className="text-orange-500 fill-orange-500" size={18} />
            Hot Recommendations
        </h3>

        <div className="grid grid-cols-2 gap-4">
            <GameCard title="Win Go" desc="Elite Prediction" color="red" onClick={() => setView('GAME_WINGO')} icon="🎱" />
            <GameCard title="Aviator" desc="High Stakes Crash" color="blue" onClick={() => setView('GAME_AVIATOR')} icon="✈️" />
            <GameCard title="Mines" desc="Treasure Hunt" color="indigo" onClick={() => setView('GAME_MINES')} icon="💣" />
            <GameCard title="Dog Road" desc="Lane Sprint" color="orange" onClick={() => setView('GAME_DOG')} icon="🐕" />
            <GameCard title="Lucky Wheel" desc="Premium Spin" color="purple" onClick={() => setView('GAME_VORTEX')} icon="🎡" />
        </div>
      </div>
    </div>
  );
};

export default Home;

import React, { useState } from 'react';
import { Lock, Smartphone, User, Mail, Crown } from 'lucide-react';
import { login, register } from '../services/mockFirebase';

const Auth: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [inviteCode, setInviteCode] = useState('');
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault(); setError(''); setLoading(true);
    if (isLogin) {
        const res = await login(phone, password);
        if (!res.success) setError(res.message || 'Invalid credentials');
    } else {
        if (!username) { setError('Username is required'); setLoading(false); return; }
        const res = await register(phone, password, inviteCode, username);
        if (!res.success) setError(res.message || 'Registration failed');
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-[#0a0f1d] flex flex-col items-center justify-center p-6 relative overflow-hidden font-sans">
        <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-b from-yellow-500/10 to-transparent"></div>

        <div className="w-full max-w-md bg-[#111827] rounded-3xl p-8 shadow-2xl relative z-10 border border-slate-800">
            <div className="flex flex-col items-center mb-8">
                <Crown size={40} className="text-yellow-500 mb-2 fill-yellow-500" />
                <h1 className="text-3xl font-black text-white italic tracking-tighter gold-text">CLUB 61</h1>
                <p className="text-slate-500 text-xs mt-2 uppercase tracking-[0.2em]">The Elite Gaming Network</p>
            </div>

            <div className="flex bg-[#0a0f1d] p-1 rounded-full mb-6 border border-slate-800">
                <button 
                    onClick={() => setIsLogin(true)} 
                    className={`flex-1 py-3 rounded-full text-xs font-black uppercase tracking-widest transition-all ${isLogin ? 'bg-yellow-600 text-black shadow-lg shadow-yellow-500/20' : 'text-slate-500'}`}
                >
                    Log In
                </button>
                <button 
                    onClick={() => setIsLogin(false)} 
                    className={`flex-1 py-3 rounded-full text-xs font-black uppercase tracking-widest transition-all ${!isLogin ? 'bg-yellow-600 text-black shadow-lg shadow-yellow-500/20' : 'text-slate-500'}`}
                >
                    Register
                </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="bg-[#0a0f1d] rounded-xl flex items-center px-4 py-3 border border-slate-800 focus-within:border-yellow-500/50 transition-all">
                    <Smartphone size={18} className="text-slate-500 mr-3"/>
                    <span className="text-slate-500 mr-2 text-sm font-bold">+91</span>
                    <input 
                        type="tel" 
                        className="bg-transparent text-white w-full outline-none font-bold" 
                        placeholder="Phone Number" 
                        value={phone} 
                        onChange={e => setPhone(e.target.value)}
                    />
                </div>

                {!isLogin && (
                    <div className="bg-[#0a0f1d] rounded-xl flex items-center px-4 py-3 border border-slate-800 focus-within:border-yellow-500/50 transition-all">
                        <User size={18} className="text-slate-500 mr-3"/>
                        <input 
                            type="text" 
                            className="bg-transparent text-white w-full outline-none font-bold" 
                            placeholder="Username" 
                            value={username} 
                            onChange={e => setUsername(e.target.value)}
                        />
                    </div>
                )}

                <div className="bg-[#0a0f1d] rounded-xl flex items-center px-4 py-3 border border-slate-800 focus-within:border-yellow-500/50 transition-all">
                    <Lock size={18} className="text-slate-500 mr-3"/>
                    <input 
                        type="password" 
                        className="bg-transparent text-white w-full outline-none font-bold" 
                        placeholder="Password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)}
                    />
                </div>

                {!isLogin && (
                    <div className="bg-[#0a0f1d] rounded-xl flex items-center px-4 py-3 border border-slate-800 focus-within:border-yellow-500/50 transition-all">
                        <Mail size={18} className="text-slate-500 mr-3"/>
                        <input 
                            type="text" 
                            className="bg-transparent text-white w-full outline-none font-bold" 
                            placeholder="Invite Code (Optional)" 
                            value={inviteCode} 
                            onChange={e => setInviteCode(e.target.value)}
                        />
                    </div>
                )}

                {error && <p className="text-red-500 text-[10px] text-center font-black uppercase tracking-widest">{error}</p>}

                <button 
                    type="submit" 
                    disabled={loading} 
                    className="w-full bg-gradient-to-r from-yellow-500 to-yellow-600 text-black font-black py-4 rounded-xl shadow-xl shadow-yellow-500/10 mt-6 active:scale-95 transition-all uppercase tracking-widest text-sm"
                >
                    {loading ? 'Authenticating...' : (isLogin ? 'Enter Club' : 'Join Club')}
                </button>
            </form>

            <p className="text-center text-[10px] text-slate-600 mt-8 uppercase font-bold tracking-widest">Premium Membership Access Only</p>
        </div>
    </div>
  );
};
export default Auth;

import React, { useState, useEffect } from 'react';
import { Users, Copy, ChevronRight, BarChart3, CreditCard, QrCode, X, Phone, MessageCircle, Share2, FileText, User, CheckCircle2, Crown } from 'lucide-react';
import { referralStats, getSubordinates, getCommissions, subscribeToBalance } from '../services/mockFirebase';

const Referral: React.FC = () => {
  const [showRules, setShowRules] = useState(false);
  const [showSubordinates, setShowSubordinates] = useState(false);
  const [showCommissions, setShowCommissions] = useState(false);
  const [showService, setShowService] = useState(false);
  const [activeTab, setActiveTab] = useState<'DIRECT' | 'TEAM'>('DIRECT');
  const [, setTick] = useState(0); 
  const [showToast, setShowToast] = useState(false);

  useEffect(() => {
      const unsub = subscribeToBalance(() => {
          setTick(t => t + 1);
      });
      return unsub;
  }, []);

  const subordinates = getSubordinates();
  const commissions = getCommissions();

  const handleCopy = (text: string) => {
      navigator.clipboard.writeText(text);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 2000);
  };

  const handleShare = async () => {
      const shareData = {
          title: 'Join CLUB 61!',
          text: `Join the elite CLUB 61 network. Register using my link to win high rewards!`,
          url: referralStats.link
      };

      if (navigator.share) {
          try {
              await navigator.share(shareData);
          } catch (err) {
              console.log(err);
          }
      } else {
          handleCopy(referralStats.link);
      }
  };

  const handleServiceRedirect = (type: 'TELEGRAM' | 'WHATSAPP') => {
      const number = "919339409219";
      if (type === 'TELEGRAM') {
          window.open(`https://t.me/+${number}`, '_blank');
      } else {
          window.open(`https://wa.me/${number}`, '_blank');
      }
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen pb-24 font-sans relative">
      {showToast && (
          <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 bg-black/90 text-white px-8 py-3 rounded-full font-black text-xs flex items-center gap-3 border border-yellow-500/20 animate-in zoom-in duration-200">
              <CheckCircle2 className="text-yellow-500" size={16}/> LINK COPIED
          </div>
      )}

      <div className="bg-gradient-to-br from-[#1e293b] to-[#0a0f1d] p-6 pt-10 pb-20 rounded-b-[3rem] text-white shadow-xl relative overflow-hidden border-b border-yellow-500/20">
        <div className="absolute top-0 right-0 p-32 bg-yellow-500/5 rounded-full blur-3xl -mr-16 -mt-16"></div>

        <div className="flex flex-col items-center relative z-10">
            <Crown className="text-yellow-500 mb-2 fill-yellow-500" size={24} />
            <h1 className="text-center font-black text-sm mb-8 tracking-[0.2em] uppercase gold-text">Agency Management</h1>

            <div className="text-center mb-4">
                <h2 className="text-6xl font-black mb-1 drop-shadow-2xl gold-text tracking-tighter">₹{referralStats.yesterdayCommission.toFixed(2)}</h2>
                <p className="text-yellow-100 text-[10px] font-black uppercase tracking-widest bg-yellow-500/10 inline-block px-5 py-1.5 rounded-full border border-yellow-500/20 backdrop-blur-sm">Yesterday's Bonus</p>
            </div>
            <p className="text-center text-[10px] text-slate-500 font-bold uppercase tracking-widest">Lifetime Earnings: ₹{referralStats.totalCommission.toFixed(2)}</p>
        </div>
      </div>

      <div className="px-4 -mt-12 relative z-10">
        <div className="bg-[#111827] rounded-3xl overflow-hidden shadow-2xl mb-6 border border-slate-800">
            <div className="flex border-b border-slate-800">
                <button 
                    onClick={() => setActiveTab('DIRECT')}
                    className={`flex-1 p-4 transition-all duration-300 ${activeTab === 'DIRECT' ? 'bg-yellow-500/5 border-b-2 border-yellow-500 text-yellow-500' : 'text-slate-500'}`}
                >
                    <span className="text-[10px] font-black uppercase tracking-widest">Direct Tier</span>
                </button>
                <button 
                    onClick={() => setActiveTab('TEAM')}
                    className={`flex-1 p-4 transition-all duration-300 ${activeTab === 'TEAM' ? 'bg-yellow-500/5 border-b-2 border-yellow-500 text-yellow-500' : 'text-slate-500'}`}
                >
                     <span className="text-[10px] font-black uppercase tracking-widest">Network Tier</span>
                </button>
            </div>

            <div className="grid grid-cols-2 text-center p-8 gap-y-10">
                <div className="border-r border-slate-800">
                    <div className="text-2xl font-black text-white">
                        {activeTab === 'DIRECT' ? referralStats.directSubordinates : referralStats.teamSubordinates}
                    </div>
                    <div className="text-[9px] text-slate-500 uppercase font-black tracking-widest mt-2">Registers</div>
                </div>
                <div>
                    <div className="text-2xl font-black text-white">
                        ₹{referralStats.totalBetAmount.toFixed(0)}
                    </div>
                    <div className="text-[9px] text-slate-500 uppercase font-black tracking-widest mt-2">Volume</div>
                </div>
                <div className="border-r border-slate-800">
                    <div className="text-2xl font-black text-green-500">0</div>
                    <div className="text-[9px] text-slate-500 uppercase font-black tracking-widest mt-2">Depositors</div>
                </div>
                 <div>
                    <div className="text-2xl font-black text-green-500">₹0</div>
                    <div className="text-[9px] text-slate-500 uppercase font-black tracking-widest mt-2">First Bonus</div>
                </div>
            </div>
        </div>

        <button 
            onClick={handleShare}
            className="w-full bg-gradient-to-r from-yellow-500 to-yellow-600 py-4 rounded-2xl text-black font-black text-sm shadow-xl shadow-yellow-900/20 mb-8 transition-all active:scale-95 flex items-center justify-center gap-3 uppercase tracking-widest"
        >
            <Share2 size={20}/>
            Generate Invite
        </button>

        <div className="space-y-4">
             <div onClick={() => handleCopy(referralStats.code)} className="bg-[#111827] p-5 rounded-2xl flex items-center justify-between cursor-pointer active:bg-slate-800 transition-colors border border-slate-800">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-xl bg-yellow-500/10 text-yellow-500 flex items-center justify-center">
                        <Copy size={22} />
                    </div>
                    <span className="text-white font-black text-xs uppercase tracking-widest">Referral ID</span>
                </div>
                <div className="flex items-center gap-2 bg-[#0a0f1d] px-3 py-1.5 rounded-lg border border-slate-800">
                    <span className="text-yellow-500 font-black tracking-tighter">{referralStats.code}</span>
                    <Copy size={14} className="text-slate-600" />
                </div>
            </div>

            <MenuItem onClick={() => setShowSubordinates(true)} icon={BarChart3} label="Elite Data" />
            <MenuItem onClick={() => setShowCommissions(true)} icon={CreditCard} label="Bonus History" />
            <MenuItem onClick={() => setShowRules(true)} icon={FileText} label="Club Policies" />
            <MenuItem onClick={() => setShowService(true)} icon={Users} label="VIP Support" />
        </div>
      </div>

      {showRules && (
          <FullPageModal title="Club Policies" onClose={() => setShowRules(false)}>
              <div className="text-slate-400 text-sm space-y-4 font-medium leading-relaxed">
                  <p className="bg-yellow-500/5 p-4 rounded-xl border border-yellow-500/20 text-yellow-500 font-bold">1. Earn 50% instant bonus on all primary tier deposits.</p>
                  <div className="grid grid-cols-2 gap-3">
                      <div className="bg-[#0a0f1d] p-4 rounded-xl border border-slate-800">
                          <p className="text-[9px] text-slate-600 font-black uppercase mb-1">Direct Profit</p>
                          <p className="font-black text-xl text-yellow-500">50%</p>
                      </div>
                      <div className="bg-[#0a0f1d] p-4 rounded-xl border border-slate-800">
                          <p className="text-[9px] text-slate-600 font-black uppercase mb-1">Rebate</p>
                          <p className="font-black text-xl text-blue-500">0.6%</p>
                      </div>
                  </div>
              </div>
          </FullPageModal>
      )}

      {showSubordinates && (
          <FullPageModal title="Elite Subordinates" onClose={() => setShowSubordinates(false)}>
              <div className="space-y-3">
                  {subordinates.length > 0 ? subordinates.map(sub => (
                      <div key={sub.id} className="bg-[#0a0f1d] p-4 rounded-2xl flex justify-between items-center border border-slate-800">
                          <div className="flex items-center gap-3">
                              <div className="w-10 h-10 rounded-full bg-yellow-500/10 flex items-center justify-center text-yellow-500 font-black">C</div>
                              <div>
                                  <div className="font-black text-white text-xs">UID: {sub.uid.slice(-6)}</div>
                                  <div className="text-[9px] text-slate-600 mt-1 uppercase">Bet: ₹{sub.betAmount}</div>
                              </div>
                          </div>
                          <div className="text-right">
                              <div className="text-yellow-500 font-black text-sm">+₹{sub.commission.toFixed(2)}</div>
                              <div className="text-[9px] text-slate-700 font-bold uppercase">{sub.date}</div>
                          </div>
                      </div>
                  )) : <div className="text-center text-slate-700 py-20 font-black uppercase tracking-widest text-xs opacity-50 italic">No Members in Group</div>}
              </div>
          </FullPageModal>
      )}

      {showService && (
          <FullPageModal title="VIP Concierge" onClose={() => setShowService(false)}>
              <div className="flex flex-col items-center justify-center py-10">
                  <div className="w-24 h-24 bg-yellow-500/10 rounded-full flex items-center justify-center mb-6 border border-yellow-500/20">
                      <Crown size={48} className="text-yellow-500 fill-yellow-500"/>
                  </div>
                  <h3 className="text-white font-black text-xl mb-8 uppercase tracking-widest gold-text">Priority Line</h3>
                  <div className="w-full space-y-4">
                      <button onClick={() => handleServiceRedirect('TELEGRAM')} className="w-full bg-[#1e293b] text-white py-4 rounded-2xl flex items-center justify-center gap-3 font-black uppercase text-xs border border-slate-700 shadow-lg">
                          <MessageCircle size={20} className="text-[#229ED9]"/> Official Telegram
                      </button>
                      <button onClick={() => handleServiceRedirect('WHATSAPP')} className="w-full bg-[#1e293b] text-white py-4 rounded-2xl flex items-center justify-center gap-3 font-black uppercase text-xs border border-slate-700 shadow-lg">
                          <Phone size={20} className="text-[#25D366]"/> WhatsApp Concierge
                      </button>
                  </div>
                  <p className="text-slate-600 text-[10px] font-black text-center mt-10 uppercase tracking-widest">Elite Service Active 24/7</p>
              </div>
          </FullPageModal>
      )}
    </div>
  );
};

const MenuItem = ({ icon: Icon, label, onClick }: any) => (
    <div onClick={onClick} className="bg-[#111827] p-5 rounded-2xl flex items-center justify-between cursor-pointer active:bg-slate-800 transition-all border border-slate-800 group shadow-md">
        <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-[#0a0f1d] text-slate-600 flex items-center justify-center group-hover:bg-yellow-500 group-hover:text-black transition-all">
                <Icon size={22} />
            </div>
            <span className="text-white font-black text-xs uppercase tracking-widest">{label}</span>
        </div>
        <ChevronRight size={18} className="text-slate-700 group-hover:text-yellow-500 transition-all" />
    </div>
