                    <div className={`px-4 py-1 rounded-full font-black text-sm flex items-center gap-2 ${gameState.status === 'BETTING' ? 'bg-green-600' : 'bg-red-600'}`}>
                        <Clock size={16}/> {gameState.timeLeft}s
                    </div>
                </div>

                <div className="flex justify-around items-center h-64 relative">
                    {/* Dragon Side */}
                    <div className="flex flex-col items-center">
                        <div className={`w-28 h-40 rounded-xl border-4 flex items-center justify-center text-4xl font-black bg-slate-900 ${gameState.status === 'RESULT' ? 'border-yellow-500' : 'border-slate-800 animate-pulse'}`}>
                            {getCardDisplay(gameState.dragonCard)}
                        </div>
