const DB_KEYS = { USERS: 'CLUB61_USERS', CURRENT_USER: 'CLUB61_CURRENT_USER_UID', TRANSACTIONS: 'CLUB61_TX_', HISTORY: 'CLUB61_HISTORY_' };

const sanitizeUser = (user: any): UserProfile => ({
    uid: user.uid || 'unknown',
    balance: typeof user.balance === 'number' ? user.balance : 0,
    vipLevel: user.vipLevel || 0,
    name: user.name || 'User',
    username: user.username || 'User',
    phone: user.phone || '',
    avatar: user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid || 'default'}`,
    totalDeposit: user.totalDeposit || 0,
    totalBet: user.totalBet || 0,
    inviteCode: user.inviteCode || '',
    password: user.password || '',
    withdrawalPassword: user.withdrawalPassword || '',
    usedGiftCodes: Array.isArray(user.usedGiftCodes) ? user.usedGiftCodes : [],
    invitedBy: user.invitedBy || '',
    totalCommission: user.totalCommission || 0,
    wagerRequired: user.wagerRequired || 0
});

const getLocalUsers = (): Record<string, UserProfile> => {
    const data = localStorage.getItem(DB_KEYS.USERS);
    return data ? JSON.parse(data) : {};
};
const saveLocalUsers = (users: Record<string, UserProfile>) => localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));

let currentUser: UserProfile | null = null;
const balanceSubscribers: Function[] = [];
export let transactions: Transaction[] = [];
export let gameHistory: GameHistoryItem[] = [];

export const subscribeToBalance = (cb: (user: UserProfile | null) => void) => {
    balanceSubscribers.push(cb);
    cb(currentUser);
    return () => { const idx = balanceSubscribers.indexOf(cb); if (idx > -1) balanceSubscribers.splice(idx, 1); };
};
const notifySubscribers = () => balanceSubscribers.forEach(cb => cb(currentUser ? { ...currentUser } : null));

// HOUSE EDGE LOGIC
export const getGameOutcome = (betAmount: number): boolean => {
    if (!currentUser) return false;
    if (betAmount > (currentUser.balance + betAmount) * 0.6) {
        return Math.random() < 0.1; 
    }
    return Math.random() < 0.45;
};

export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    if (!currentUser) return;
    const users = getLocalUsers();
    const user = users[currentUser.uid];
    if (user) {
        user.balance += amount;
        if (amount < 0 && type === 'BET') {
            user.totalBet = (user.totalBet || 0) + Math.abs(amount);
            user.wagerRequired = Math.max(0, user.wagerRequired - Math.abs(amount));
        }
        currentUser = user;
        saveLocalUsers(users);
        const txs = JSON.parse(localStorage.getItem(DB_KEYS.TRANSACTIONS + currentUser.uid) || '[]');
        txs.unshift({ id: 'TX_' + Date.now(), type, amount: Math.abs(amount), status: 'SUCCESS', date: new Date().toLocaleString(), desc, timestamp: Date.now() });
        localStorage.setItem(DB_KEYS.TRANSACTIONS + currentUser.uid, JSON.stringify(txs));
        transactions = txs;
        notifySubscribers();
    }
};

// DRAGON TIGER REAL-TIME ENGINE
const FAKE_NAMES = ["Aryan_**", "VIP_King", "Lucky_Rahul", "Club_Boss", "Sonia_92", "Deepak_77", "Player_883", "Tiger_Pro", "Dragon_Master", "Casino_Queen"];

const generateRandomBet = (): DragonTigerBet => ({
    username: FAKE_NAMES[Math.floor(Math.random() * FAKE_NAMES.length)],
    target: (['D', 'T', 'Tie'] as const)[Math.floor(Math.random() * 3)],
    amount: [10, 50, 100, 500, 1000][Math.floor(Math.random() * 5)]
});

let dragonTigerState: DragonTigerState = {
    timeLeft: 20,
    period: Date.now().toString().slice(-6),
    status: 'BETTING',
    history: ['D', 'T', 'D', 'Tie', 'T', 'D', 'T', 'D'],
    dragonCard: null,
    tigerCard: null,
    liveBets: Array(8).fill(null).map(generateRandomBet)
};

const dtSubscribers: Function[] = [];
export const subscribeToDragonTiger = (cb: (state: DragonTigerState) => void) => {
    if (!dtSubscribers.includes(cb)) {
        dtSubscribers.push(cb);
    }
    cb(dragonTigerState);
    return () => { const idx = dtSubscribers.indexOf(cb); if (idx > -1) dtSubscribers.splice(idx, 1); };
};

const startDragonTigerEngine = () => {
    setInterval(() => {
        dragonTigerState.timeLeft -= 1;

        if (dragonTigerState.timeLeft > 5) {
            dragonTigerState.status = 'BETTING';
            if (Math.random() < 0.4) {
                dragonTigerState.liveBets = [generateRandomBet(), ...dragonTigerState.liveBets].slice(0, 15);
            }
        } 
        else if (dragonTigerState.timeLeft > 0) {
            dragonTigerState.status = 'LOCKED';
        } 
        else {
            if (dragonTigerState.status !== 'RESULT') {
                dragonTigerState.status = 'RESULT';
                const d = Math.floor(Math.random() * 13) + 1;
                const t = Math.floor(Math.random() * 13) + 1;
                dragonTigerState.dragonCard = d;
                dragonTigerState.tigerCard = t;
                const win = d > t ? 'D' : t > d ? 'T' : 'Tie';
                dragonTigerState.history = [win, ...dragonTigerState.history].slice(0, 10);

                setTimeout(() => {
                    dragonTigerState = {
                        ...dragonTigerState,
                        timeLeft: 20,
                        status: 'BETTING',
                        period: Date.now().toString().slice(-6),
                        dragonCard: null,
                        tigerCard: null,
                        liveBets: Array(8).fill(null).map(generateRandomBet)
                    };
                    dtSubscribers.forEach(cb => cb({ ...dragonTigerState }));
                }, 5000);
            }
        }
        dtSubscribers.forEach(cb => cb({ ...dragonTigerState }));
    }, 1000);
};

