const init = () => {
    const uid = localStorage.getItem(DB_KEYS.CURRENT_USER);
    if (uid) {
        const users = getLocalUsers();
        if (users[uid]) {
            currentUser = sanitizeUser(users[uid]);
            transactions = JSON.parse(localStorage.getItem(DB_KEYS.TRANSACTIONS + uid) || '[]');
            gameHistory = JSON.parse(localStorage.getItem(DB_KEYS.HISTORY + uid) || '[]');
        }
    }
    startDragonTigerEngine();
};

