// AUDIO SYSTEM - Safe lazy loading
let isMuted = false;
const audioCache: Record<string, HTMLAudioElement> = {};

const getAudio = (url: string) => {
    if (audioCache[url]) return audioCache[url];
    const audio = document.createElement('audio');
    audio.src = url;
    audio.preload = 'auto';
    audioCache[url] = audio;
    return audio;
};

const SOUND_URLS = {
  click: 'https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3',
  win: 'https://assets.mixkit.co/active_storage/sfx/2000/2000-preview.mp3',
  loss: 'https://assets.mixkit.co/active_storage/sfx/203/203-preview.mp3',
  tick: 'https://assets.mixkit.co/active_storage/sfx/2578/2578-preview.mp3',
  cardFlip: 'https://assets.mixkit.co/active_storage/sfx/2006/2006-preview.mp3',
  spin: 'https://assets.mixkit.co/active_storage/sfx/2003/2003-preview.mp3',
  plane: 'https://assets.mixkit.co/active_storage/sfx/1547/1547-preview.mp3'
};

export const toggleMute = () => { isMuted = !isMuted; return isMuted; };
export const getMuteStatus = () => isMuted;
export const playSound = (type: keyof typeof SOUND_URLS) => {
  if (isMuted) return;
  try { 
      const audio = getAudio(SOUND_URLS[type]); 
      if (audio) { 
          audio.currentTime = 0; 
          audio.volume = 0.5; 
