                const tVal = dragonTigerState.tigerCard || 0;
                const winner: 'D' | 'T' | 'Tie' = dVal > tVal ? 'D' : tVal > dVal ? 'T' : 'Tie';

                dragonTigerState.history = [winner, ...dragonTigerState.history].slice(0, 10);
                dragonTigerState.timeLeft = 5;
            } else {
                dragonTigerState.status = 'BETTING';
                dragonTigerState.period = (parseInt(dragonTigerState.period) + 1).toString();
                dragonTigerState.timeLeft = 30;
                dragonTigerState.dragonCard = null;
                dragonTigerState.tigerCard = null;
                dragonTigerState.liveBets = Array(5).fill(0).map(() => ({
                    username: `User_${Math.floor(Math.random() * 9999)}`,
                    target: (['D', 'T', 'Tie'][Math.floor(Math.random() * 3)]) as 'D' | 'T' | 'Tie',
                    amount: [10, 50, 100, 500][Math.floor(Math.random() * 4)]
                }));
            }
        }
        dragonTigerSubscribers.forEach(cb => cb({ ...dragonTigerState }));
    }, 1000);
};

