import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Menu, Volume2, VolumeX, Wallet, History, Loader2 } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, getGameHistory } from '../services/mockFirebase';
import { GameResult } from '../types';

interface AviatorProps {
  onBack: () => void;
  userBalance: number;
  onResult: (result: GameResult) => void;
}

type GamePhase = 'WAITING' | 'FLYING' | 'CRASHED';

const Aviator: React.FC<AviatorProps> = ({ onBack, userBalance, onResult }) => {
  const [phase, setPhase] = useState<GamePhase>('WAITING');
  const [multiplier, setMultiplier] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [history, setHistory] = useState<number[]>([1.22, 2.45, 1.05, 8.12, 1.11, 3.44, 12.01, 1.00]);

  const activeBetRef = useRef(false);
  const [activeBet, setActiveBet] = useState(false); 

  const nextRoundBetRef = useRef(false);
  const [nextRoundBet, setNextRoundBet] = useState(false);

  const [waitTime, setWaitTime] = useState(5); 

  const crashPointRef = useRef(0);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    const prevGames = getGameHistory('Aviator');
    if (prevGames.length > 0) {
        const points = prevGames.map(g => {
            const match = g.details.match(/@ ([\d\.]+)x/);
            return match ? parseFloat(match[1]) : 1.00;
        }).slice(0, 15);
        if (points.length > 0) setHistory(points);
    }

    startWaitingPhase();
    return () => {
        isMounted.current = false;
        if (animationRef.current) cancelAnimationFrame(animationRef.current);
        stopAllSounds();
    }
  }, []);

  const handleToggleMute = () => {
      setMuted(toggleMute());
  };

  const startWaitingPhase = () => {
      if (!isMounted.current) return;
      setPhase('WAITING');
      setMultiplier(1.00);
      setWaitTime(5);

      const canvas = canvasRef.current;
      if (canvas) {
          const ctx = canvas.getContext('2d');
          if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
      }

      if (activeBetRef.current) {
          activeBetRef.current = false;
          setActiveBet(false);
      }

      let t = 5;
      const interval = setInterval(() => {
          if (!isMounted.current) {
              clearInterval(interval);
              return;
          }
          t -= 0.1;
          setWaitTime(Math.max(0, t));
          if (t <= 0) {
              clearInterval(interval);
              startFlyingPhase();
          }
      }, 100);
  };

  const startFlyingPhase = () => {
      if (!isMounted.current) return;

      // Handle queued bets
      if (nextRoundBetRef.current) {
          if (userBalance < betAmount) {
              nextRoundBetRef.current = false;
              setNextRoundBet(false);
              alert("Insufficient Balance for queued bet!");
          } else {
              activeBetRef.current = true;
              setActiveBet(true);
              nextRoundBetRef.current = false;
              setNextRoundBet(false);
              updateBalance(-betAmount, 'BET', 'Aviator');
              playSound('click');
          }
      }

      setPhase('FLYING');
      playSound('plane'); 

      const r = Math.random();
      let cp = 1.0;
      if (r < 0.3) cp = 1.0 + Math.random() * 0.5;
      else if (r < 0.6) cp = 1.5 + Math.random();
      else cp = 1.0 + Math.random() * 10; 
      crashPointRef.current = parseFloat(cp.toFixed(2));

      startTimeRef.current = Date.now();
      animateGame();
  };

  const animateGame = () => {
    if (!isMounted.current) return;
    const now = Date.now();
    const elapsed = (now - startTimeRef.current) / 1000;
    const currentMult = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.08);

    if (currentMult >= crashPointRef.current) {
        handleCrash(crashPointRef.current);
    } else {
        setMultiplier(currentMult);
        drawGraph(currentMult, elapsed, false);
        animationRef.current = requestAnimationFrame(animateGame);
    }
  };

  const handleCrash = (finalMult: number) => {
      if (!isMounted.current) return;
      setPhase('CRASHED');
      setMultiplier(finalMult);
      const finalElapsed = (Date.now() - startTimeRef.current) / 1000;
      drawGraph(finalMult, finalElapsed, true);
      playSound('loss');
      setHistory(prev => [finalMult, ...prev].slice(0, 15));

      if (activeBetRef.current) {
          activeBetRef.current = false;
          setActiveBet(false);
          addGameHistory('Aviator', betAmount, 0, `Crashed @ ${finalMult.toFixed(2)}x`);
          onResult({
              win: false,
              amount: betAmount,
              game: 'Aviator',
              period: Date.now().toString(),
              resultDetails: [{label: 'Crash', value: `${finalMult.toFixed(2)}x`, color: 'bg-red-500'}]
          });
      }

      setTimeout(() => {
          if (isMounted.current) startWaitingPhase();
      }, 3000);
  };

  const handleBetAction = () => {
      if (phase === 'WAITING' || phase === 'CRASHED') {
          const newState = !nextRoundBetRef.current;
          if (newState && betAmount > userBalance) {
              alert("Insufficient Balance!");
              return;
          }
          nextRoundBetRef.current = newState;
          setNextRoundBet(newState);
      } else if (phase === 'FLYING') {
          if (activeBetRef.current) {
              const winAmount = betAmount * multiplier;
              updateBalance(winAmount, 'WIN', 'Aviator Win');
              activeBetRef.current = false;
              setActiveBet(false);
              playSound('win');
              addGameHistory('Aviator', betAmount, winAmount, `Cashed @ ${multiplier.toFixed(2)}x`);
              onResult({
                win: true,
                amount: winAmount,
                game: 'Aviator',
                period: Date.now().toString(),
                resultDetails: [{label: 'Cashout', value: `${multiplier.toFixed(2)}x`, color: 'bg-green-500'}]
            });
          } else {
              const newState = !nextRoundBetRef.current;
              if (newState && betAmount > userBalance) {
                  alert("Insufficient Balance!");
                  return;
              }
              nextRoundBetRef.current = newState;
              setNextRoundBet(newState);
          }
      }
  };

  const drawGraph = (currentMult: number, elapsed: number, isCrash: boolean) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      canvas.width = window.innerWidth;
      const width = canvas.width;
      const height = canvas.height;

      ctx.clearRect(0, 0, width, height);
      const timeScale = Math.max(5, elapsed * 1.3); 
      const multScale = Math.max(2, currentMult * 1.3);

      const getX = (t: number) => (t / timeScale) * width;
      const getY = (m: number) => height - ((m - 1) / (multScale - 1)) * height;

      // Draw Grid
      ctx.strokeStyle = '#333';
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      const step = Math.ceil(multScale / 5);
      for(let i=1; i<multScale; i+=step) {
          const y = getY(i);
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.fillStyle = '#666';
          ctx.font = '10px Arial';
          ctx.fillText(`${i}x`, 5, y - 5);
      }
      ctx.stroke();

      // Draw Curve
      ctx.beginPath();
      ctx.moveTo(0, height); 
      const plotStep = 0.05;
      for (let t = 0; t <= elapsed; t += plotStep) {
          const m = 1 + (t * 0.1) + (Math.pow(t, 2) * 0.08);
          ctx.lineTo(getX(t), getY(m));
      }

      const endX = getX(elapsed);
      const endY = getY(currentMult);
      ctx.lineTo(endX, endY);

      if (!isCrash) {
        // Shadow/Fill
        ctx.lineTo(endX, height);
        ctx.lineTo(0, height);
        ctx.closePath();
        const gradient = ctx.createLinearGradient(0, endY, 0, height);
        gradient.addColorStop(0, 'rgba(239, 68, 68, 0.7)');
        gradient.addColorStop(1, 'rgba(127, 29, 29, 0.1)');
        ctx.fillStyle = gradient;
        ctx.fill();
      }

      // Main Line
      ctx.beginPath();
      ctx.moveTo(0, height);
      for (let t = 0; t <= elapsed; t += plotStep) {
          const m = 1 + (t * 0.1) + (Math.pow(t, 2) * 0.08);
          ctx.lineTo(getX(t), getY(m));
      }
      ctx.lineTo(endX, endY);
      ctx.strokeStyle = '#ef4444'; 
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();

      // Plane Icon (Simple Triangle)
      if (!isCrash) {
        ctx.save();
        ctx.translate(endX, endY);
        const prevT = Math.max(0, elapsed - 0.1);
        const prevM = 1 + (prevT * 0.1) + (Math.pow(prevT, 2) * 0.08);
        const dy = getY(currentMult) - getY(prevM);
        const dx = getX(elapsed) - getX(prevT);
        const angle = Math.atan2(dy, dx);
        ctx.rotate(angle); 
        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        ctx.moveTo(15, 0); ctx.lineTo(-10, 8); ctx.lineTo(-5, 0); ctx.lineTo(-10, -8);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }
  };

  return (
    <div className="bg-black min-h-screen flex flex-col font-sans text-white">
       {/* Header */}
       <div className="bg-black p-2 flex items-center justify-between border-b border-gray-800 z-10">
        <div className="flex items-center gap-2">
            <button onClick={onBack} className="p-2 hover:bg-slate-800 rounded-full"><ArrowLeft className="text-gray-400" size={18}/></button>
            <span className="text-red-600 font-black italic text-2xl tracking-wider uppercase">Aviator</span>
        </div>
        <div className="flex gap-4 items-center">
             <div className="flex items-center gap-2 bg-gray-900 px-3 py-1 rounded-full border border-gray-700">
                 <Wallet size={14} className="text-green-500" />
                 <span className="text-sm font-bold">₹{userBalance.toFixed(2)}</span>
             </div>
             <button onClick={handleToggleMute} className="p-1">
                 {muted ? <VolumeX size={20} className="text-gray-400" /> : <Volume2 size={20} className="text-gray-400" />}
             </button>
             <Menu size={20} className="text-gray-400"/>
        </div>
      </div>

      {/* History Strip */}
      <div className="bg-[#1a1a1a] p-1 flex gap-1 overflow-x-auto no-scrollbar border-b border-gray-800">
          <div className="flex px-2 py-1 bg-black rounded-lg text-[10px] text-gray-500 font-black items-center mr-2 uppercase tracking-tighter shrink-0">History</div>
          {history.map((m, i) => (
              <div key={i} className={`flex-shrink-0 px-3 py-1 rounded text-xs font-black font-mono bg-gray-800 border border-gray-700 ${m < 2 ? 'text-blue-400' : m < 10 ? 'text-purple-400' : 'text-pink-500'}`}>
                  {m.toFixed(2)}x
              </div>
          ))}
      </div>

      {/* Game Stage */}
      <div className="relative flex-1 bg-black flex flex-col overflow-hidden">
        {phase === 'WAITING' && (
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/60 backdrop-blur-[1px]">
                 <div className="text-xl font-black uppercase tracking-[0.3em] text-gray-400 mb-4 animate-pulse">Waiting for next round</div>
                 <div className="w-64 h-1.5 bg-gray-800 rounded-full overflow-hidden border border-white/5">
                     <div className="h-full bg-red-600 transition-all duration-100 ease-linear shadow-[0_0_10px_rgba(220,38,38,0.5)]" style={{ width: `${(waitTime / 5) * 100}%` }}></div>
                 </div>
            </div>
        )}

        {(phase === 'FLYING' || phase === 'CRASHED') && (
             <div className="absolute top-[20%] left-1/2 -translate-x-1/2 z-20 text-center">
                 {phase === 'CRASHED' && (
                     <div className="text-red-600 font-black text-2xl uppercase mb-1 tracking-widest animate-in zoom-in duration-200 drop-shadow-lg">
                         FLEW AWAY!
                     </div>
                 )}
                 <div className={`text-7xl sm:text-8xl font-black drop-shadow-2xl font-mono tracking-tighter ${phase === 'CRASHED' ? 'text-red-600' : 'text-white'}`}>
                     {multiplier.toFixed(2)}x
                 </div>
             </div>
        )}

        <canvas ref={canvasRef} height={400} className="absolute inset-0 z-10 w-full h-full" />
      </div>

      {/* Control Panel */}
      <div className="bg-[#151515] p-2 sm:p-4 border-t-2 border-red-600 z-30 shadow-[0_-10px_30px_rgba(0,0,0,0.5)]">
          <div className="bg-[#0a0a0a] rounded-2xl p-3 border border-white/5 relative overflow-hidden">
               <div className="flex flex-row gap-3 h-auto items-stretch">
                   {/* Bet Adjuster */}
                   <div className="flex-[2] flex flex-col justify-center min-w-0">
                       <div className="flex items-center bg-[#1a1a1a] rounded-xl border border-gray-800 h-12 sm:h-14 relative shadow-inner">
                           <button onClick={() => setBetAmount(Math.max(10, betAmount - 10))} disabled={activeBet} className="w-10 sm:w-12 h-full text-gray-500 text-2xl font-black active:scale-90 transition-transform">-</button>
                           <input type="number" value={betAmount} readOnly className="flex-1 bg-transparent text-center text-white font-black text-lg sm:text-xl outline-none min-w-0" />
                           <button onClick={() => setBetAmount(betAmount + 10)} disabled={activeBet} className="w-10 sm:w-12 h-full text-gray-500 text-2xl font-black active:scale-90 transition-transform">+</button>
                       </div>
                       <div className="flex gap-1.5 mt-2">
                           {[100, 500, 1000].map(amt => (
                               <button key={amt} onClick={() => !activeBet && setBetAmount(amt)} className="flex-1 py-2 bg-[#1a1a1a] rounded-lg text-[10px] font-black text-gray-500 border border-gray-800 hover:text-white hover:bg-slate-800 transition-all">{amt}</button>
                           ))}
                       </div>
                   </div>

                   {/* Action Button */}
                   <button 
                        onClick={handleBetAction}
                        className={`flex-[2] sm:w-48 rounded-xl flex flex-col items-center justify-center shadow-2xl transition-all active:scale-95 px-2 py-3 border-b-4 ${
                            activeBet && phase === 'FLYING'
                            ? 'bg-orange-500 border-orange-700 hover:bg-orange-400' 
                            : activeBet || nextRoundBet 
                                ? 'bg-red-700 border-red-900 shadow-none translate-y-0.5' 
                                : 'bg-green-600 border-green-800 hover:bg-green-500' 
                        }`}
                   >
                        <span className="text-white font-black text-xs sm:text-sm uppercase leading-none mb-1 tracking-widest">
                            {activeBet && phase === 'FLYING' ? 'CASH OUT' : (activeBet || nextRoundBet ? 'CANCEL' : 'STAKE BET')}
                        </span>
                        {activeBet && phase === 'FLYING' ? (
                            <span className="text-white font-black text-lg sm:text-2xl leading-none font-mono">₹{(betAmount * multiplier).toFixed(2)}</span>
                        ) : (
                            <span className="text-white/80 font-black text-sm sm:text-lg leading-none font-mono">{betAmount} INR</span>
                        )}
                   </button>
               </div>

               {nextRoundBet && phase !== 'WAITING' && (
                   <div className="absolute inset-0 bg-black/90 backdrop-blur-[2px] flex items-center justify-center z-10 animate-in fade-in">
                       <div className="text-red-500 font-black uppercase tracking-[0.2em] text-xs border-2 border-red-500 px-6 py-2 rounded-full bg-black shadow-[0_0_20px_rgba(239,68,68,0.3)]">Queued for next round</div>
                   </div>
               )}
          </div>
      </div>
    </div>
  );
};

